INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-boebert-loses-co4', 'lauren-boebert-loses-colorado-4th-district-eileen-laubacher', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Lauren Boebert loses her House seat as retired Navy admiral Eileen Laubacher flips Colorado''s 4th District', 'The Associated Press called the race on Friday, Nov. 13, with Laubacher ahead by about 3,400 votes in a district Trump carried by more than 18 points in 2024.', 'Republican Rep. Lauren Boebert will lose her seat in Congress to Democrat Eileen Laubacher in Colorado''s 4th Congressional District, the Associated Press projected on Friday, Nov. 13, ten days after the Nov. 3 election. With about 99% of the expected vote counted, Laubacher had 48.8% to Boebert''s 47.9%, a lead of about 3,400 votes, ABC News reported.

## A Republican stronghold

Trump carried the eastern Colorado district by more than 18 points in 2024, according to Anadolu Agency. Boebert won it by more than 11 points that year after moving from the 3rd District, where she had survived in 2022 by just 546 votes, CNN reported via KCRA.

## Who won

Laubacher is a U.S. Naval Academy graduate and retired rear admiral who served more than three decades in the Navy and later worked as senior director for South Asia on the National Security Council under President Joe Biden, ABC News reported. She ran on affordability.

## Boebert''s response

Boebert said on X that she had called Laubacher to congratulate her and told supporters to "stay tuned" about her plans. Trump endorsed her days before the election after the two clashed earlier in the year, when she campaigned for Rep. Thomas Massie and joined the push to force release of the Epstein case files, KCRA reported. The result is pending state certification.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:32100:32162/full/pct:25/0/default.jpg', 'A grain elevator in Holly, Prowers County, in Colorado''s eastern plains (file). Photo: Carol M. Highsmith / Library of Congress (highsm.32162), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 8, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
