INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-miller-first-week', 'stephen-miller-first-week-chief-of-staff-lobbyist-memo-cabinet', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Stephen Miller''s first week as chief of staff: more say for Cabinet secretaries and new limits on lobbyists', 'In two memos, Trump''s new chief of staff loosened the West Wing''s hold on Cabinet messaging and required counsel approval before staff meet registered lobbyists at the White House, according to CNN and The Jerusalem Post.', 'Stephen Miller has moved quickly to reshape the West Wing since replacing Susie Wiles as White House chief of staff, CNN reported on Saturday, Nov. 14. Trump announced the change on Friday, Nov. 6, after the midterm elections.

## Two memos

Miller issued two memos in his first week, CNN reported. One gives Cabinet secretaries more control over their own announcements and messaging, scrapping a Wiles-era rule that required West Wing sign-off on administration appearances. The other tightens access for lobbyists: White House employees now need advance approval from the White House Counsel''s Office before holding policy meetings with registered lobbyists on White House grounds, The Jerusalem Post reported. The memo, sent to all staff on Thursday, Nov. 12, is not a blanket ban, and the Office of Public Liaison remains the main contact for outside groups.

## A tighter circle

Miller has routed more decisions through his own office, relies on a small group of allies and has promised to crack down on leaks, according to CNN. He has not yet held an all-staff meeting while personnel changes continue, and one official told CNN that staff feel they are "walking on eggshells." Some officials welcomed the looser approach to the Cabinet; skeptics worried it could make the White House more chaotic. White House spokesman Taylor Rogers said the Cabinet trusts Miller and that he will carry out Trump''s agenda.

## What is next

Miller and other officials are preparing executive actions for next year, CNN reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:13500:13552/full/pct:25/0/default.jpg', 'The White House, with the Washington Monument under scaffolding and the Jefferson Memorial beyond, 1998 (file). Photo: Carol M. Highsmith / Library of Congress (highsm.13552), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 8, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
