INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-east-potomac-golf-ruling', 'judge-reyes-blocks-east-potomac-park-golf-course-closure', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge blocks Trump administration from closing East Potomac Park for its planned golf course rebuild', 'U.S. District Judge Ana Reyes acted on Saturday, Nov. 14, hours before a 15-month closure was due to begin. Her order runs through Saturday, Nov. 28, unless the court acts sooner.', 'A federal judge in Washington on Saturday, Nov. 14, temporarily barred the Trump administration from closing East Potomac Park and its public golf course, just before a 15-month closure was set to start on Sunday, Nov. 15, the Associated Press reported via ABC News.

## The order

U.S. District Judge Ana Reyes ordered the government to keep the park and golf course open during the hours they were open as of Nov. 14. The order lasts through Saturday, Nov. 28, or until the court rules otherwise. It does not require the government to actively manage either site, and repairs can continue with the required notice. Reyes said Trump''s social media posts suggested the plan was final and that the closure would go ahead, which weighed in the plaintiffs'' favor.

## The fight

Trump wants to turn the golf course in the 106-year-old park along the Potomac River, about 2 miles from the White House, into a championship-level venue. The DC Preservation League and two local golfers sued in February, arguing the plan would change the course''s character and price out regular players; Trump disputes that. The Justice Department says planning can continue and that the National Park Service may limit access where the public could be harmed.

## What comes next

Reyes said she plans to appoint Jessie Liu, a former U.S. attorney for the District of Columbia, as a special master to examine whether officials or Justice Department lawyers broke ethics rules or misled the court. The department has asked that Reyes be removed from the case; she has not stepped aside, the AP reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:cph:3c30000:3c35000:3c35400:3c35450/full/pct:50/0/default.jpg', 'East Potomac Golf Club, Washington, aerial view from above Hains Point looking north toward the Mall (historical file). Photo: Library of Congress Prints and Photographs Division (cph.3c35450, item 2005676856). Editor: confirm "no known restrictions" on the item record', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 7, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
