INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-wild-bruins', 'wild-6-bruins-2-hartman-yurov-second-straight-home-loss', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Wild 6, Bruins 2: Minnesota scores four in the second period and hands Boston a second straight home loss', 'Ryan Hartman and Danila Yurov scored twice each at TD Garden on Saturday, Nov. 14, as the Wild stretched their point streak to 11 games. David Pastrnak and Fraser Minten scored for the Bruins.', 'The Minnesota Wild beat the Bruins 6-2 at TD Garden on Saturday, Nov. 14, handing Boston consecutive home losses for the first time this season, NHL.com reported. The Bruins fell to 13-6-1, two days after a 5-2 loss to Montreal.

## How it happened

Ryan Hartman opened the scoring 6:54 into the first period. Minnesota then broke the game open in the second with goals from Quinn Hughes 53 seconds in, Blake Coleman at 2:00 and Hartman again at 10:00, according to ESPN''s scoring summary. Fraser Minten scored on a Bruins power play at 8:45 of the second, and David Pastrnak made it 4-2 early in the third before Danila Yurov scored twice, the second into an empty net.

## By the numbers

Boston outshot Minnesota 32-25, but Wild goalie Jesper Wallstedt made 30 saves. Jeremy Swayman stopped 19 shots for the Bruins. The Wild improved to 15-3-4, extended their point streak to 11 games and won their eighth straight road game. Defenseman Brock Faber had an assist in his season debut after recovering from a skull fracture suffered in September, NHL.com reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:12100:12101/full/pct:25/0/default.jpg', 'Charles River cityscape, Boston (file). Photo: Carol M. Highsmith / Library of Congress (highsm.12101), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 8, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261115-wild-bruins-src1', 'bd-20261115-wild-bruins', 'Wild cruise past Bruins, run point streak to 11 games', 'https://www.nhl.com/bruins/news/minnesota-wild-boston-bruins-game-recap-november-14-2026-x4576', 'NHL.com', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-15T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-15. Editor to confirm.', 'newsroom-assistant', '2026-11-15T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261115-wild-bruins-src2', 'bd-20261115-wild-bruins', 'Wild 6-2 Bruins (Nov 14, 2026) Final Score', 'https://www.espn.com/nhl/game/_/gameId/401892709/wild-bruins', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-15T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-15. Editor to confirm.', 'newsroom-assistant', '2026-11-15T10:45:00.000Z');
