INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-notre-dame-boston-college', 'notre-dame-41-boston-college-7-carr-walton', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Notre Dame 41, Boston College 7: The Irish lead 31-0 at halftime and the Eagles fall to 4-6', 'CJ Carr threw two touchdown passes and Jonaz Walton ran for 141 yards in South Bend on Saturday, Nov. 14. Boston College finished with 136 total yards.', 'No. 5 Notre Dame routed Boston College 41-7 in South Bend, Ind., on Saturday, Nov. 14, scoring 24 points in the second quarter to lead 31-0 at halftime, CBS Sports reported. The Irish improved to 9-1; the Eagles dropped to 4-6.

## The Irish offense

Quarterback CJ Carr completed 20 of 28 passes for 217 yards and two touchdowns, including a 26-yard score to Micah Gilbert. Jonaz Walton ran for 141 yards and a touchdown, and Nolan James Jr. added 73 yards and a score. Jaylen Sneed returned a fumble for a touchdown, and Spencer Porath kicked field goals of 40 and 37 yards, according to CBS Sports.

## Boston College

The Eagles were held to 136 total yards. Their only touchdown was a 3-yard run by Bo MacCormack III in the third quarter. Boston College plays its next game at home against Syracuse; Notre Dame hosts SMU. Notre Dame is No. 5 in the College Football Playoff rankings.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:41200:41242/full/pct:25/0/default.jpg', 'A statue of Jesus on the campus of the University of Notre Dame, South Bend, Ind. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.41242), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 7, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
