INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-utah-arizona', 'utah-40-arizona-39-dampier-whittemore-70-yard-touchdown', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Utah 40, Arizona 39: Devon Dampier''s 70-yard strike with 2:25 left keeps the No. 2 Utes unbeaten', 'Dampier accounted for four touchdowns in Tucson in a game delayed three hours by the FAA ground stop and finished early Sunday, Nov. 15. Utah is 10-0.', 'No. 2 Utah stayed unbeaten with a 40-39 win at No. 23 Arizona in a game that ended early Sunday, Nov. 15, ESPN reported. The Utes are 10-0 and 7-0 in the Big 12.

## The finish

Arizona took a 39-33 lead when Noah Fifita threw a 10-yard touchdown pass to Isaiah Mizell with just over three minutes left. Utah answered on the next possession, as quarterback Devon Dampier hit Creed Whittemore for a 70-yard touchdown with 2:25 remaining. Utah''s defense then stopped Arizona on fourth down to close it out.

## The numbers

Dampier threw for 204 yards and two touchdowns and ran for 100 yards and two more, though he also threw an interception and lost a fumble, KSAT reported. Daniel Bray ran for 197 yards. Fifita passed for 356 yards and three touchdowns, two to Mizell. Arizona fell to 7-3.

## A late start

Utah did not reach Tucson until just after noon on Saturday, Nov. 14, because of the FAA''s nationwide ground stop the day before, and kickoff was pushed back three hours. The Utes fell behind by 11 points early. The win extended Utah''s winning streak to 16 games over two seasons, ESPN reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04200:04283/full/pct:25/0/default.jpg', 'Saguaro cactus near Tucson, Ariz. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04283), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 7, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261115-utah-arizona-src1', 'bd-20261115-utah-arizona', 'No. 2 Utah survives, stays unbeaten on late 70-yard TD in thriller vs. Arizona', 'https://www.espn.com/college-football/story/_/id/50488650/no-2-utah-survives-late-70-yard-td-thriller-vs-arizona', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-15T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-15. Editor to confirm.', 'newsroom-assistant', '2026-11-15T10:45:00.000Z');
