INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261115-texas-lsu', 'texas-22-lsu-21-manning-raleek-brown-touchdown-3-seconds', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Texas 22, LSU 21: Arch Manning finds Raleek Brown with 3 seconds left to stun the Tigers in Baton Rouge', 'Texas drove 58 yards in the final 2:19 on Saturday, Nov. 14, after Manning had thrown three interceptions. Jelani McDonald picked off LSU''s Sam Leavitt three times.', 'No. 6 Texas beat No. 21 LSU 22-21 at Tiger Stadium on Saturday, Nov. 14, when Arch Manning threw a 4-yard touchdown pass to Raleek Brown with 3 seconds left, the Associated Press reported via WHIO. The rankings are from the College Football Playoff committee.

## The final drive

Texas trailed 21-16 when it took over at its own 42 with 2:19 to play. Manning converted three third downs, two with his legs, before finding Brown along the left sideline for the winning score.

## A messy night

Manning finished 19 of 35 for 174 yards with one touchdown pass and three interceptions, and he also ran for an early touchdown. LSU quarterback Sam Leavitt threw for 244 yards and two touchdowns to Jackson Harris, but Texas safety Jelani McDonald intercepted him three times. Dilin Jones broke a 44-yard touchdown run that gave LSU a 21-10 lead in the third quarter, and LSU missed a 38-yard field goal at the end of the first half.

## Standings

Texas improved to 8-2 and 5-2 in the SEC. LSU fell to 6-4 and 3-4.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:12500:12532/full/pct:25/0/default.jpg', 'The Louisiana State Capitol, Baton Rouge (file). Photo: Carol M. Highsmith / Library of Congress (highsm.12532), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-15.sql', 6, 0, 'newsroom-assistant', '2026-11-15T10:45:00.000Z', '2026-11-15T10:45:00.000Z');
